/bin/bash -lc "python - <<'PY'
from bioblend.galaxy import GalaxyInstance
from pathlib import Path
import json
key=Path('/run/secrets/galaxy_api_key').read_text().strip()
gi=GalaxyInstance('https://usegalaxy.org', key=key)
for tid in ['toolshed.g2.bx.psu.edu/repos/devteam/bwa/bwa_mem/0.7.19+galaxy1','toolshed.g2.bx.psu.edu/repos/iuc/samtools_depth/samtools_depth/1.22+galaxy1']:
    t=gi.tools.show_tool(tid, io_details=True)
    print('\\n###', tid)
    def clean(obj):
        if isinstance(obj, dict):
            keep={k:v for k,v in obj.items() if k in ['name','type','label','value','test_param','cases','inputs','options','optional','multiple','extensions','argument']}
            if 'options' in keep and isinstance(keep['options'], list):
                keep['options']=keep['options'][:10]
            return {k:clean(v) for k,v in keep.items()}
        if isinstance(obj, list): return [clean(x) for x in obj]
        return obj
    print(json.dumps(clean(t['inputs']), indent=2)[:40000])
PY"
